import{R as e,e as t,f as i,U as s}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"Installation & Setup","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/installation-setup.md","filePath":"get-started/installation-setup.md","lastUpdated":1659761043000}'),n={name:"get-started/installation-setup.md"};function l(o,a,r,p,h,c){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="installation-setup" tabindex="-1">Installation &amp; Setup <a class="header-anchor" href="#installation-setup" aria-label="Permalink to &quot;Installation &amp; Setup&quot;">​</a></h1><p>You can install Formie via the plugin store, or through Composer.</p><h2 id="craft-plugin-store" tabindex="-1">Craft Plugin Store <a class="header-anchor" href="#craft-plugin-store" aria-label="Permalink to &quot;Craft Plugin Store&quot;">​</a></h2><p>To install <strong>Formie</strong>, navigate to the <em>Plugin Store</em> section of your Craft control panel, search for <code>Formie</code>, and click the <em>Try</em> button.</p><h2 id="composer" tabindex="-1">Composer <a class="header-anchor" href="#composer" aria-label="Permalink to &quot;Composer&quot;">​</a></h2><p>You can also add the package to your project using Composer and the command line.</p><ol><li>Open your terminal and go to your Craft project:</li></ol><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/project</span></span></code></pre></div><ol start="2"><li>Then tell Composer to require the plugin, and Craft to install it:</li></ol><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verbb/formie</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin/install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> formie</span></span></code></pre></div><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><p>You can try Formie in a development environment for as long as you like. Once your site goes live, you are required to purchase a license for the plugin.</p><p>For more information, see <a href="https://craftcms.com/docs/4.x/plugins.html#commercial-plugin-licensing" target="_blank" rel="noreferrer">Craft&#39;s Commercial Plugin Licensing</a>.</p>',13)])])}const g=e(n,[["render",l]]);export{u as __pageData,g as default};
